import{NextRequest,NextResponse}from'next/server';import{z}from'zod';import{requireActiveAdmin}from'@/lib/admin-auth';import{createAdminClient}from'@/lib/supabase/admin'
const schema=z.object({vendorName:z.string().trim().min(1).max(200),category:z.string().trim().min(1).max(100),contactPerson:z.string().trim().max(150).nullable().optional(),mobile:z.string().trim().max(40).nullable().optional(),email:z.string().trim().email().max(320).nullable().optional(),location:z.string().trim().max(150).nullable().optional(),address:z.string().trim().max(1000).nullable().optional(),description:z.string().trim().max(4000).nullable().optional(),internalNotes:z.string().trim().max(4000).nullable().optional(),isActive:z.boolean()})
export async function GET(_:NextRequest,{params}:{params:Promise<{id:string}>}){const a=await requireActiveAdmin();if('response'in a)return a.response;const{id}=await params;const{data,error}=await createAdminClient().from('event_vendors').select('*').eq('id',id).maybeSingle();if(error)return NextResponse.json({error:'Unable to load vendor'},{status:500});return data?NextResponse.json({vendor:data}):NextResponse.json({error:'Vendor not found'},{status:404})}
export async function PATCH(r:NextRequest,{params}:{params:Promise<{id:string}>}){const a=await requireActiveAdmin();if('response'in a)return a.response;const{id}=await params;let body:unknown;try{body=await r.json()}catch{return NextResponse.json({error:'Invalid JSON'},{status:400})}const p=schema.safeParse(body);if(!p.success)return NextResponse.json({error:'Please check the vendor details'},{status:400});const{error}=await createAdminClient().from('event_vendors').update({vendor_name:p.data.vendorName,category:p.data.category,contact_person:p.data.contactPerson||null,mobile:p.data.mobile||null,email:p.data.email||null,location:p.data.location||null,address:p.data.address||null,description:p.data.description||null,internal_notes:p.data.internalNotes||null,is_active:p.data.isActive}).eq('id',id);return error?NextResponse.json({error:'Unable to update vendor'},{status:500}):NextResponse.json({ok:true})}
export async function DELETE(_:NextRequest,{params}:{params:Promise<{id:string}>}){const a=await requireActiveAdmin();if('response'in a)return a.response;const{id}=await params,db=createAdminClient(),{count,error:assignmentError}=await db.from('event_vendor_assignments').select('id',{count:'exact',head:true}).eq('vendor_id',id);if(assignmentError)return NextResponse.json({error:'Unable to check vendor assignments'},{status:500});if(count)return NextResponse.json({error:'A vendor with booking assignments cannot be deleted. Deactivate it instead.'},{status:409});const{data,error}=await db.from('event_vendors').delete().eq('id',id).select('id').maybeSingle();if(error)return NextResponse.json({error:'Unable to delete vendor'},{status:500});return data?NextResponse.json({ok:true}):NextResponse.json({error:'Vendor not found'},{status:404})}
